records = []
for line in log_text.strip().split("\n"):
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
        if "update" in d and "mean_return" in d:
            records.append(d)
    except Exception:
        pass

print(f"Total parsed records: {len(records)}")

# Let's inspect intervals
intervals = [
    ("Updates 1-50", records[:50]),
    ("Updates 51-100", records[50:100]),
    ("Updates 101-150", records[100:150]),
    ("Updates 151-200", records[150:200]),
    ("Updates 201-237", records[200:]),
    ("Last 50 (188-237)", records[-50:]),
]

for name, recs in intervals:
    avg_ret = sum(r["mean_return"] for r in recs) / len(recs)
    avg_kill = sum(r["kill_rate"] for r in recs) / len(recs)
    avg_pac = sum(r["pacman_score"] for r in recs) / len(recs)
    avg_ent = sum(r["entropy"] for r in recs) / len(recs)
    avg_vloss = sum(r["value_loss"] for r in recs) / len(recs)
    avg_aloss = sum(r["actor_loss"] for r in recs) / len(recs)
    avg_bcloss = sum(r["bc_loss"] for r in recs) / len(recs)
    avg_bcprob = sum(r["bc_prob"] for r in recs) / len(recs)
    avg_bccoef = sum(r["bc_coef"] for r in recs) / len(recs)
    avg_kl = sum(r["approx_kl"] for r in recs) / len(recs)
    avg_clip = sum(r["clip_frac"] for r in recs) / len(recs)
    print(f"--- {name} (N={len(recs)}) ---")
    print(f"  Return: {avg_ret:.2f} | Kill Rate: {avg_kill:.1%} | Pacman Score: {avg_pac:.1f}")
    print(f"  Entropy: {avg_ent:.3f} | Value Loss: {avg_vloss:.4f} | Actor Loss: {avg_aloss:.5f}")
    print(f"  KL: {avg_kl:.5f} | Clip Frac: {avg_clip:.2%} | BC Prob: {avg_bcprob:.2f} | BC Loss: {avg_bcloss:.3f}")

# Check Curriculum conditions:
print("\n=== CURRICULUM CHECK (STAGES[0]) ===")
print("Stage 0 targets: advance_return = -7.0, target_kill_rate = 0.34, min_updates = 150")
last50 = records[-50:]
avg_ret_50 = sum(r["mean_return"] for r in last50) / 50
avg_kill_50 = sum(r["kill_rate"] for r in last50) / 50
print(f"Last 50 Updates Rolling Avg Return: {avg_ret_50:.2f} (Target: >= -7.0)")
print(f"Last 50 Updates Rolling Avg Kill Rate: {avg_kill_50:.1%} (Target: >= 34.0%)")

# Gate 1: Dominant Gate
dominant_gate = max(0.50, min(0.95, 0.34 * 1.15)) # 0.50
print(f"Dominant Gate: kill >= {dominant_gate:.1%}, ret >= -9.0 -> PASS? {avg_kill_50 >= dominant_gate and avg_ret_50 >= -9.0}")

# Gate 2: Solid Target Gate
print(f"Solid Target Gate: ret >= -7.0 and kill >= 34.0% -> PASS? {avg_ret_50 >= -7.0 and avg_kill_50 >= 0.34}")

# Gate 3: Plateau Gate
half = 25
hist_ret = [r["mean_return"] for r in last50]
avg_first = sum(hist_ret[:half]) / half
avg_second = sum(hist_ret[half:]) / half
diff = avg_second - avg_first
comp_kill = 0.34 * 0.90
plateau_pass = (diff < 0.5) and (avg_kill_50 >= comp_kill or avg_ret_50 >= -7.0)
print(f"Plateau Gate: updates({len(records)}) >= 200, diff({diff:.2f}) < 0.5, and (kill >= {comp_kill:.1%} or ret >= -7.0) -> PASS? {plateau_pass}")
